-- 0115 — Contractor & Owner-Operator Operations. Nested organizations are commercial relationships, not fake user roles.
CREATE TABLE `organizationRelationships` (`id` int NOT NULL AUTO_INCREMENT,`relationshipRef` varchar(64) NOT NULL,`parentOrgRef` varchar(40) NOT NULL,`childOrgRef` varchar(40) NOT NULL,`relationshipType` enum('PRIME_CONTRACTOR','CONTRACTOR','SUBCONTRACTOR','VENDOR','LEASED_OWNER_OPERATOR','INDEPENDENT_CARRIER','EQUIPMENT_PROVIDER') NOT NULL,`status` enum('pending','active','suspended','ended') NOT NULL DEFAULT 'pending',`effectiveFrom` timestamp NOT NULL,`effectiveTo` timestamp NULL,`createdByUserId` int NOT NULL,`createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY (`id`),UNIQUE KEY `organizationRelationships_relationshipRef_unique` (`relationshipRef`),UNIQUE KEY `organizationRelationships_pair_type_unique` (`parentOrgRef`,`childOrgRef`,`relationshipType`),KEY `organizationRelationships_parent_idx` (`parentOrgRef`,`status`),KEY `organizationRelationships_child_idx` (`childOrgRef`,`status`));
CREATE TABLE `contractorBusinessProfiles` (`id` int NOT NULL AUTO_INCREMENT,`orgRef` varchar(40) NOT NULL,`operatingMode` enum('LEASED_OWNER_OPERATOR','INDEPENDENT_CONTRACTOR','INDEPENDENT_CARRIER','CONTRACTOR_COMPANY') NOT NULL,`legalName` varchar(220) NOT NULL,`carrierNumber` varchar(80) NULL,`status` enum('active','suspended','closed') NOT NULL DEFAULT 'active',`createdByUserId` int NOT NULL,`createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY (`id`),UNIQUE KEY `contractorBusinessProfiles_orgRef_unique` (`orgRef`));
CREATE TABLE `organizationWorkers` (`id` int NOT NULL AUTO_INCREMENT,`workerRef` varchar(64) NOT NULL,`orgRef` varchar(40) NOT NULL,`userId` int NULL,`operatorId` int NULL,`workerType` enum('OWNER_DRIVER','EMPLOYEE_DRIVER','CO_DRIVER','SWAMPER','LABORER','EQUIPMENT_OPERATOR','HELPER','SHOP_HAND','MECHANIC','MAINTENANCE_SUPERVISOR','BOOKKEEPER','DISPATCHER','SAFETY_COMPLIANCE','OFFICE_ADMIN') NOT NULL,`compensationType` enum('HOURLY','SALARY','DAY_RATE','LOAD_RATE','KM_RATE','PERCENTAGE','PIECE_RATE','CONTRACT_RATE') NULL,`status` enum('active','inactive','ended') NOT NULL DEFAULT 'active',`effectiveFrom` timestamp NOT NULL,`effectiveTo` timestamp NULL,`createdByUserId` int NOT NULL,`createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY (`id`),UNIQUE KEY `organizationWorkers_workerRef_unique` (`workerRef`),KEY `organizationWorkers_org_idx` (`orgRef`,`status`));
CREATE TABLE `commercialJobChains` (`id` int NOT NULL AUTO_INCREMENT,`chainRef` varchar(80) NOT NULL,`rootJobId` int NOT NULL,`parentChainRef` varchar(80) NULL,`assigningOrgRef` varchar(40) NOT NULL,`performingOrgRef` varchar(40) NOT NULL,`customerOrgRef` varchar(40) NULL,`operatingCarrierOrgRef` varchar(40) NULL,`equipmentOwnerOrgRef` varchar(40) NULL,`relationshipType` enum('EMPLOYEE','LEASED_OWNER_OPERATOR','INDEPENDENT_CONTRACTOR','SUBCONTRACTOR','INDEPENDENT_CARRIER') NOT NULL,`status` enum('assigned','accepted','active','complete','cancelled') NOT NULL DEFAULT 'assigned',`createdByUserId` int NOT NULL,`createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY (`id`),UNIQUE KEY `commercialJobChains_chainRef_unique` (`chainRef`),KEY `commercialJobChains_job_idx` (`rootJobId`),KEY `commercialJobChains_performing_idx` (`performingOrgRef`,`status`));
CREATE TABLE `jobCrewAssignments` (`id` int NOT NULL AUTO_INCREMENT,`assignmentRef` varchar(80) NOT NULL,`chainRef` varchar(80) NOT NULL,`unitId` int NOT NULL,`primaryDriverWorkerRef` varchar(64) NOT NULL,`coDriverWorkerRef` varchar(64) NULL,`additionalCrewJson` text NOT NULL,`startsAt` timestamp NOT NULL,`endsAt` timestamp NULL,`createdByUserId` int NOT NULL,`createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY (`id`),UNIQUE KEY `jobCrewAssignments_assignmentRef_unique` (`assignmentRef`),KEY `jobCrewAssignments_chain_idx` (`chainRef`),KEY `jobCrewAssignments_unit_idx` (`unitId`,`startsAt`));
CREATE TABLE `privateRateSchedules` (`id` int NOT NULL AUTO_INCREMENT,`rateRef` varchar(80) NOT NULL,`ownerOrgRef` varchar(40) NOT NULL,`counterpartyOrgRef` varchar(40) NOT NULL,`chainRef` varchar(80) NULL,`compensationType` enum('HOURLY','SALARY','DAY_RATE','LOAD_RATE','KM_RATE','PERCENTAGE','PIECE_RATE','CONTRACT_RATE') NOT NULL,`rateCents` int NOT NULL,`currency` varchar(3) NOT NULL DEFAULT 'CAD',`effectiveFrom` timestamp NOT NULL,`effectiveTo` timestamp NULL,`createdByUserId` int NOT NULL,`createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY (`id`),UNIQUE KEY `privateRateSchedules_rateRef_unique` (`rateRef`),KEY `privateRateSchedules_owner_idx` (`ownerOrgRef`,`counterpartyOrgRef`));
